function cellInfo(a1){var r=ss.getSheetByName('Board Summary').getRange(a1);return {a1:a1,val:r.getValue(),formula:r.getFormula(),display:r.getDisplayValue(),fmt:r.getNumberFormat(),font:r.getFontColor(),bg:r.getBackground()};}
var sh=ss.getSheetByName('Board Summary');
log(JSON.stringify({
  d7d25: sh.getRange('D7:D25').getFontColors().map(r=>r[0]),
  f5g5: [cellInfo('F5'), cellInfo('G5')],
  rules: sh.getConditionalFormatRules().map((rule,i)=>{var bc=rule.getBooleanCondition(); return {i:i,ranges:rule.getRanges().map(r=>r.getA1Notation()), type: bc? String(bc.getCriteriaType()): null, vals: bc? bc.getCriteriaValues(): null};}),
