var sh=ss.getSheetByName('Board Summary');
var rule=sh.getConditionalFormatRules()[0];
var bc=rule.getBooleanCondition();
var dv=sh.getRange('G5').getDataValidation();
var vals=dv.getCriteriaValues();
var rng=vals[0];
log(JSON.stringify({
  rule:{ranges:rule.getRanges().map(r=>r.getA1Notation()), type:String(bc.getCriteriaType()), criteria:bc.getCriteriaValues(), font:bc.getFontColor(), bg:bc.getBackground(), bold:bc.getBold()},
  dv:{type:String(dv.getCriteriaType()), rangeA1:rng.getA1Notation?rng.getA1Notation():null, rangeSheet:rng.getSheet?rng.getSheet().getName():null, showDropdown:vals[1]}
},null,2));

var sh = ss.getSheetByName('Board Summary');

// Populate Board Summary outputs in column D
sh.getRange('D7').setFormula("='Deal Inputs'!$D$21/1000000");
sh.getRange('D8').setFormula("='Deal Inputs'!$D$18");
sh.getRange('D9').setFormula("=TEXT('Deal Inputs'!$D$24,\"0%\")&\" Cash / \"&TEXT('Deal Inputs'!$D$25,\"0%\")&\" Stock\"");
sh.getRange('D12').setFormula("='Pro Forma'!$H$21/1000");
sh.getRange('D13').setFormula("=('Pro Forma'!$H$38+'Google Model'!$J$102+'Meta Model'!$J$87+'Deal Inputs'!$D$91)/1000");
sh.getRange('D14').setFormula("='Valuation'!$H$23/1000");
sh.getRange('D17:D19').setFormulas([
  ["='Pro Forma'!$D$51"],
  ["='Pro Forma'!$E$51"],
  ["='Pro Forma'!$F$51"]
]);
sh.getRange('D22').setFormula("=('Google Model'!$F$129+'Meta Model'!$F$114)*1000/'Pro Forma'!$E$21");
sh.getRange('D23').setFormula("=('Google Model'!$F$129+'Meta Model'!$F$114)*1000/('Pro Forma'!$E$38+'Google Model'!$G$102+'Meta Model'!$G$87+'Deal Inputs'!$D$91)");
sh.getRange('D24').setFormula("=('Google Model'!$F$127+'Meta Model'!$F$112)*1000/'Pro Forma'!$E$45");
sh.getRange('D25').setFormula("='Valuation'!$D$79");

// Print toggle setup
sh.getRange('F5').setValue('Print?');
var g5 = sh.getRange('G5');
g5.setDataValidation(
  SpreadsheetApp.newDataValidation()
    .requireValueInRange(sh.getRange('G1:H1'), true)
    .setAllowInvalid(false)
    .build()
);
g5.setNumberFormat('"yes";;"no"');
g5.setValue(1);

// Conditional format: when G5 is yes (1), show column D in black font; otherwise preserve underlying font colors
var rule = SpreadsheetApp.newConditionalFormatRule()
  .whenFormulaSatisfied('=$G$5=1')
  .setFontColor('#000000')
  .setRanges([sh.getRange('D:D')])
  .build();
sh.setConditionalFormatRules([rule]);

SpreadsheetApp.flush();

function info(a1){
  var r = sh.getRange(a1);
  return {a1:a1, formula:r.getFormula(), value:r.getValue(), display:r.getDisplayValue(), fmt:r.getNumberFormat(), font:r.getFontColor()};
}
